import java.util.*;

public class Main {
    static int thirdMax(int[] nums) {
        TreeSet<Integer> distinct = new TreeSet<>();
        for (int x : nums) distinct.add(x);
        List<Integer> sorted = new ArrayList<>(distinct);
        Collections.reverse(sorted);                       // collect distinct values, sort them
        return sorted.size() >= 3 ? sorted.get(2) : sorted.get(0);
    }
}

