int thirdMax(vector<int>& nums) {
    set<int, greater<int>> distinct(nums.begin(), nums.end());   // collect distinct values, sorted descending
    auto it = distinct.begin();
    if (distinct.size() >= 3) { advance(it, 2); return *it; }
    return *it;
}

