#include <bits/stdc++.h>
using namespace std;

int thirdMax(vector<int>& nums) {
    optional<long long> first, second, third;
    for (int n : nums) {
        long long num = n;
        if ((first && num == *first) || (second && num == *second) || (third && num == *third)) {
            continue;                                    // skip duplicates
        }
        if (!first || num > *first) {
            third = second; second = first; first = num;
        } else if (!second || num > *second) {
            third = second; second = num;
        } else if (!third || num > *third) {
            third = num;
        }
    }
    return (int)(third ? *third : *first);
}
